"""Transport-free Search+Filter engine shared by the resident server."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any

from benchmark_harness.config import ResolvedModelProfile
from benchmark_harness.contracts import NetworkEvent
from benchmark_harness.search.volc import (
    CutoffSearchGateway,
    SearchOutcome,
    VolcSearchTransport,
)


@dataclass(frozen=True, slots=True)
class EngineSearchResult:
    """Canonical result plus transport evidence generated by one search call."""

    outcome: SearchOutcome
    network_events: tuple[NetworkEvent, ...] = ()
    filter_review_count: int = 0
    filter_model_call_count: int = 0


class SearchFilterEngine:
    """Reuse the existing Volc/cutoff/filter implementation without HTTP concerns."""

    def __init__(
        self,
        *,
        access_key_env: str = "VOLC_ACCESS_KEY_ID",
        secret_key_env: str = "VOLC_SECRET_ACCESS_KEY",
        access_key: str | None = None,
        secret_key: str | None = None,
        transport: VolcSearchTransport | None = None,
        test_only: bool = False,
        model_profile: ResolvedModelProfile | None = None,
        lookback_years: int = 5,
    ) -> None:
        self.gateway = CutoffSearchGateway(
            access_key_env=access_key_env,
            secret_key_env=secret_key_env,
            access_key=access_key,
            secret_key=secret_key,
            transport=transport,
            test_only=test_only,
            model_profile=model_profile,
            lookback_years=lookback_years,
        )
        self.test_only = test_only

    def preflight(self) -> dict[str, Any]:
        return self.gateway.preflight()

    def search(
        self,
        *,
        task_id: str,
        framework: str,
        query: str,
        cutoff_date: str,
        call_index: int,
    ) -> EngineSearchResult:
        filter_events: list[NetworkEvent] = []
        outcome = self.gateway._search(  # noqa: SLF001 - engine owns the transport seam.
            task_id=task_id,
            framework=framework,
            query=query,
            cutoff_date=cutoff_date,
            category=None,
            tool_call_count=call_index,
            network_events=filter_events,
        )
        filter_count = sum(
            1
            for audit in outcome.audit_records
            if audit.filter_stage == "llm" or audit.llm_verdict is not None
        )
        return EngineSearchResult(
            outcome=outcome,
            network_events=tuple(filter_events),
            filter_review_count=filter_count,
            filter_model_call_count=len(filter_events),
        )


__all__ = ["EngineSearchResult", "SearchFilterEngine"]
